import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Button,
  CircularProgress,
  Alert,
  useTheme,
  useMediaQuery,
} from '@mui/material';
import { Refresh } from '@mui/icons-material';

const Awards = () => {
  const [awardsData, setAwardsData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [imageLoadingStates, setImageLoadingStates] = useState({});

  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const isTablet = useMediaQuery(theme.breakpoints.down('md'));

  const SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbzvmEym2Jv76VI0ABgoIS8ZGN0Vr5_gmzCqf7Fwefoy_Y8a9O2yIXaHUfn1mQONkYMtgw/exec';

  const fetchAwardsData = async () => {
    setLoading(true);
    setError(null);
    try {
      console.log('Fetching awards data from Google Apps Script...');
      const response = await fetch(`${SCRIPT_URL}?t=${Date.now()}`);
      
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      
      const result = await response.json();
      console.log('API Response:', result);
      
      if (result.success && result.data) {
        setAwardsData(result.data);
        
        // Initialize loading states
        const initialLoadingStates = {};
        result.data.forEach((item, index) => {
          initialLoadingStates[index] = true;
        });
        setImageLoadingStates(initialLoadingStates);
      } else {
        throw new Error(result.error || 'No data received');
      }
    } catch (err) {
      console.error('Fetch error:', err);
      setError(`Error loading certificates: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  const handleImageLoad = (index) => {
    setImageLoadingStates(prev => ({
      ...prev,
      [index]: false
    }));
  };

  const handleImageError = (index, url) => {
    console.error(`Failed to load image ${index}:`, url);
    setImageLoadingStates(prev => ({
      ...prev,
      [index]: false
    }));
  };

  const getColumns = () => {
    if (isMobile) return 2;
    if (isTablet) return 3;
    return 4;
  };

  useEffect(() => {
    fetchAwardsData();
  }, []);

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="200px" flexDirection="column" gap={2}>
        <CircularProgress />
        <Typography variant="body1">Loading certificates from BT Certs folder...</Typography>
      </Box>
    );
  }

  if (error) {
    return (
      <Box p={3} display="flex" flexDirection="column" alignItems="center" gap={2}>
        <Alert severity="error" sx={{ width: '100%', maxWidth: 400 }}>
          {error}
        </Alert>
        <Button variant="contained" startIcon={<Refresh />} onClick={fetchAwardsData}>
          Try Again
        </Button>
      </Box>
    );
  }

  return (
    <Box sx={{ p: { xs: 1, sm: 2, md: 3 }, maxWidth: 1200, margin: '0 auto' }}>
      <Typography variant="h4" component="h1" align="center" gutterBottom sx={{ fontSize: { xs: '1.75rem', sm: '2.5rem', md: '3rem' }, mb: 1 }}>
        Awards & Certificates
      </Typography>
      
      <Typography variant="h6" component="p" align="center" color="text.secondary" sx={{ mb: 3 }}>
        {awardsData.length} {awardsData.length === 1 ? 'certificate' : 'certificates'} from BT Certs folder
      </Typography>

      {awardsData.length === 0 ? (
        <Box textAlign="center" p={3}>
          <Typography variant="body1" color="text.secondary" gutterBottom>
            No certificates found in BT Certs folder.
          </Typography>
          <Button variant="outlined" startIcon={<Refresh />} onClick={fetchAwardsData} sx={{ mt: 2 }}>
            Refresh
          </Button>
        </Box>
      ) : (
        <Box sx={{ columnCount: getColumns(), columnGap: 1, '& > *': { breakInside: 'avoid', marginBottom: 1, display: 'inline-block', width: '100%' } }}>
          {awardsData.map((item, idx) => (
            <Box key={idx} sx={{ borderRadius: 2, overflow: 'hidden', boxShadow: 1, transition: 'all 0.3s ease', backgroundColor: 'background.paper', '&:hover': { transform: 'translateY(-4px)', boxShadow: 4 }, position: 'relative' }}>
              {imageLoadingStates[idx] && (
                <Box sx={{ position: 'absolute', top: 0, left: 0, right: 0, bottom: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', backgroundColor: 'rgba(0,0,0,0.05)', zIndex: 1, minHeight: 200 }}>
                  <CircularProgress size={40} />
                </Box>
              )}
              
              <Box component="img" src={item.imageUrl} alt={item.fileName} loading="lazy" sx={{ width: '100%', height: 'auto', display: 'block', opacity: imageLoadingStates[idx] ? 0 : 1, transition: 'opacity 0.3s ease', minHeight: 200, objectFit: 'cover' }} onLoad={() => handleImageLoad(idx)} onError={() => handleImageError(idx, item.imageUrl)} />
              
              {item.description && (
                <Box sx={{ position: 'absolute', bottom: 0, left: 0, right: 0, background: 'linear-gradient(transparent, rgba(0,0,0,0.7))', color: 'white', p: 2, opacity: 0, transition: 'opacity 0.3s ease', '&:hover': { opacity: 1 } }}>
                  <Typography variant="body2" sx={{ fontSize: '0.8rem' }}>{item.description}</Typography>
                </Box>
              )}
              
              <Box sx={{ position: 'absolute', top: 0, left: 0, right: 0, background: 'linear-gradient(rgba(0,0,0,0.5), transparent)', color: 'white', p: 1, opacity: 0.8 }}>
                <Typography variant="caption" noWrap sx={{ fontSize: '0.7rem' }}>{item.fileName}</Typography>
              </Box>
            </Box>
          ))}
        </Box>
      )}
    </Box>
  );
};

export default Awards;
